{"translations":{"cue-1":"Bạn có dám tin không?","cue-2":"Âm thanh nút bấm điều hướng đầy mê hoặc của Volvo,","cue-3":"lại hoàn toàn không phải do các lập trình viên viết ra?","cue-4":"Các hãng xe khác khi làm âm thanh nút bấm,","cue-5":"đều ngồi trong văn phòng điều chỉnh thông số máy tính,","cue-6":"nhưng các nhà thiết kế của Volvo lại không làm như vậy.","cue-7":"Họ nói rằng,","cue-8":"âm thanh nút bấm này","cue-9":"chủ xe phải nghe đến hàng chục ngàn lần,","cue-10":"nên không được chói tai, không được gượng ép,","cue-11":"và càng không được gây bực bội khi nghe lâu.","cue-12":"Ngay cả khi kẹt giữa dòng xe cộ đông đúc,","cue-13":"nghe thấy nó cũng có thể khiến lòng người tĩnh lại.","cue-14":"Thế là họ đã dẫn dắt cả đội ngũ","cue-15":"lao vào khu rừng sâu và ở lại trọn hai ngày.","cue-16":"Bẻ gãy hơn ba trăm cành cây khác nhau,","cue-17":"để thử từng loại gỗ,","cue-18":"từng độ dày mỏng để xem âm thanh khi uốn gãy.","cue-19":"Hết lần này đến lần khác,","cue-20":"họ đã thu lại hơn ba trăm loại âm thanh của thiên nhiên.","cue-21":"Mục tiêu chỉ có một,","cue-22":"tìm ra một loại âm thanh","cue-23":"dịu dàng, tự nhiên, nghe một ngàn lần, mười ngàn lần","cue-24":"cũng không thấy chán ngán.","cue-25":"Cuối cùng, sau vô số lần thử nghiệm,","cue-26":"họ đã tìm thấy.","cue-27":"Khi cành sồi khẽ uốn gãy,","cue-28":"đã tạo ra tiếng răng rắc dịu dàng đó.","cue-29":"Sau đó, họ số hóa đoạn âm thanh đến từ khu rừng lớn này,","cue-30":"tinh chỉnh nhiều lần,","cue-31":"và làm mượt,","cue-32":"mới biến thành tiếng lách cách đặc trưng của nút điều hướng trên xe Volvo ngày nay.","cue-33":"Đây cũng là lý do tại sao","cue-34":"nhiều chủ xe đều nói nút bấm của Volvo","cue-35":"là nút bấm mang tính chữa lành nhất trên mạng.","cue-36":"Khi nghe âm thanh đến từ thiên nhiên này,","cue-37":"dù bên ngoài có kẹt xe đến đâu,","cue-38":"tâm trạng có bực dọc thế nào,","cue-39":"cũng có thể được xoa dịu trong chớp mắt.","cue-40":"Hóa ra cảm giác cao cấp","cue-41":"thực sự ẩn giấu trong","cue-42":"những chi tiết nhỏ dễ bị bỏ qua đó.","cue-43":"Bạn còn từng thấy trên xe hơi","cue-44":"có những thiết kế chi tiết nào ấm áp như vậy nữa không?"}}
